SET @MendingSpell := 100172;
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN @MendingSpell AND @MendingSpell+15;
DELETE FROM `spell_dbc` WHERE `ID` IN (@MendingSpell, @MendingSpell+1, @MendingSpell+2, @MendingSpell+3, @MendingSpell+4, @MendingSpell+5, @MendingSpell+6, @MendingSpell+7, @MendingSpell+8, @MendingSpell+9, @MendingSpell+10, @MendingSpell+11, @MendingSpell+12, @MendingSpell+13, @MendingSpell+14, @MendingSpell+15);

